import type { LedgerEvent, LedgerSinks } from "./types.js";
import { toLedgerEntity } from "./entity.js";

/** Flat metadata for the App Insights mirror. Correlation keys + outcome only;
 *  snippets/userRef stay in the table (avoid duplicating content into AI). */
function toMirrorAttrs(e: LedgerEvent): Record<string, string | number> {
  const a: Record<string, string | number> = {
    "ledger.agentName": e.agentName,
    "ledger.source": e.source,
    "ledger.outcome": e.outcome,
    "ledger.eventId": e.eventId,
  };
  if (e.channel) a["ledger.channel"] = e.channel;
  if (e.foundryConversationId) a["ledger.foundryConversationId"] = e.foundryConversationId;
  if (e.responseId) a["ledger.responseId"] = e.responseId;
  if (e.model) a["ledger.model"] = e.model;
  if (e.latencyMs != null) a["ledger.latencyMs"] = e.latencyMs;
  if (e.errorCode) a["ledger.errorCode"] = e.errorCode;
  return a;
}

/**
 * Build the emitLedgerEvent function. FIRE-AND-FORGET: never throws into
 * the caller, never blocks the user's reply. The write is awaited internally
 * but all errors are swallowed via onError; callers use `void emit(...)`.
 */
export function createLedgerEmitter(
  sinks: LedgerSinks,
): (e: LedgerEvent) => Promise<void> {
  const onError =
    sinks.onError ?? ((msg: string, err: unknown) => { console.warn(msg, err); });
  return async (e: LedgerEvent): Promise<void> => {
    try {
      await sinks.writeEntity(toLedgerEntity(e));
    } catch (err) {
      onError("[ledger] write failed (non-fatal)", err);
      return;
    }
    if (sinks.mirror) {
      try {
        sinks.mirror("m8t.ledger.event", toMirrorAttrs(e));
      } catch (err) {
        onError("[ledger] mirror failed (non-fatal)", err);
      }
    }
  };
}
