import type { LedgerEvent } from "./types.js";
import { makeRowKey } from "./row-key.js";

export const SNIPPET_MAX_LEN = 256;

/** Single-line, whitespace-collapsed, capped + ellipsized. Privacy-aware. */
export function truncateSnippet(text: string | undefined): string | undefined {
  if (text == null) return undefined;
  const oneLine = text.replace(/\s+/g, " ").trim();
  if (oneLine.length === 0) return undefined;
  return oneLine.length <= SNIPPET_MAX_LEN
    ? oneLine
    : oneLine.slice(0, SNIPPET_MAX_LEN) + "…";
}

/**
 * Map a LedgerEvent → an AgentLedger Table entity.
 * - PartitionKey = agentName; RowKey = descending-time (makeRowKey).
 * - The logical `timestamp` is stored physically as `eventTimestamp` to
 *   avoid Table Storage's reserved system `Timestamp` column. The brain engine
 *   reads `eventTimestamp`. (Physical detail, not a contract change.)
 * - undefined/null optional fields are omitted (Table Storage rejects them).
 * - artifacts is stored as a JSON string (Table cells are scalar); read side parses it.
 */
export function toLedgerEntity(e: LedgerEvent): Record<string, unknown> {
  const entity: Record<string, unknown> = {
    partitionKey: e.agentName,
    rowKey: makeRowKey(e.timestamp, e.eventId),
    eventId: e.eventId,
    eventTimestamp: e.timestamp,
    agentName: e.agentName,
    source: e.source,
    outcome: e.outcome,
  };
  const optional: Record<string, unknown> = {
    channel: e.channel,
    userRef: e.userRef,
    foundryConversationId: e.foundryConversationId,
    responseId: e.responseId,
    model: e.model,
    inputSnippet: truncateSnippet(e.inputSnippet),
    replySnippet: truncateSnippet(e.replySnippet),
    latencyMs: e.latencyMs,
    errorCode: e.errorCode,
    agentKind: e.agentKind,
    initiatingAgent: e.initiatingAgent,
    delegationId: e.delegationId,
    parentEventId: e.parentEventId,
    depth: e.depth,
    pendingItem: e.pendingItem,
    // Table Storage cells are scalar → serialize the pointer array to a JSON string
    // (the read side JSON.parses it). Same physical-mapping rationale as eventTimestamp.
    artifacts: e.artifacts?.length ? JSON.stringify(e.artifacts) : undefined,
  };
  for (const [k, v] of Object.entries(optional)) {
    if (v !== undefined && v !== null) entity[k] = v;
  }
  return entity;
}
