import type { AIProjectClient } from "@azure/ai-projects";
import type {
  Response,
  ResponseCreateParams,
  ResponseInputItem,
  ResponseOutputItem,
  ResponseStreamEvent,
} from "openai/resources/responses/responses";
import type { WorkerKind } from "./kind.js";

// Resolves to the direct `openai` dependency's client type returned by the
// Azure project SDK.
export type OpenAIClient = ReturnType<AIProjectClient["getOpenAIClient"]>;

export interface ResponsesTarget {
  /** The OpenAI client to call .responses.create() on. */
  client: OpenAIClient;
  /** Prompt-only: the second-arg body that names the agent. Hosted = undefined.
   *  `version` is an OPTIONAL defensive pin to THIS worker's latest known-loader
   *  version — NOT an arm selector; arms live on distinct workers. */
  extraBody?: { agent_reference: { name: string; type: "agent_reference"; version?: string } };
}

/**
 * The load-bearing prompt-vs-hosted branch. Prompt uses the shared project
 * client + an agent_reference body; hosted uses a per-agent client bound to the
 * dedicated endpoint (the SDK sets Foundry-Features: HostedAgents=V1Preview).
 * Verified live 2026-05-24 against @azure/ai-projects@2.1.1.
 */
export function resolveResponsesTarget(
  project: AIProjectClient,
  worker: { kind: WorkerKind; name: string; version?: string },
): ResponsesTarget {
  if (worker.kind === "hosted") {
    return {
      client: project.getOpenAIClient({ azureConfig: { agentName: worker.name, allowPreview: true } }),
    };
  }
  const agent_reference: { name: string; type: "agent_reference"; version?: string } = {
    name: worker.name,
    type: "agent_reference",
  };
  if (worker.version) agent_reference.version = worker.version;
  return { client: project.getOpenAIClient(), extraBody: { agent_reference } };
}

/** Minimal hosted-message shape retained for broad surface compatibility. */
export interface InvokeMessage { role: string; content: string }

export interface CollectedResponse {
  text: string;           // joined output_text.delta
  responseId: string;     // response.id (caresp_… for hosted) — ledger correlation key
  model?: string;         // response.model (empty for hosted — acceptable)
  agentSessionId?: string; // response.agent_session_id — captured for later use, currently unused
}

export interface InvokeUsage { inputTokens: number; outputTokens: number; totalTokens: number; }
export type PromptResponseTerminalState = "completed" | "failed" | "incomplete" | "error" | "eof";

export interface PromptResponseEvidence {
  text: string;
  responseId: string;
  model?: string;
  usage?: InvokeUsage;
  toolTrace: string[];
  /** Complete terminal output, or every done item observed before an abnormal terminal. */
  output: ResponseOutputItem[];
  terminalState: PromptResponseTerminalState;
}

export interface CollectedPromptResponse extends PromptResponseEvidence {
  terminalState: "completed";
}

export class PromptResponseTerminalError extends Error {
  override readonly name = "PromptResponseTerminalError";

  constructor(
    readonly terminalState: Exclude<PromptResponseTerminalState, "completed">,
    message: string,
    readonly partial: PromptResponseEvidence,
  ) {
    super(message);
  }
}

const partialEvidenceByRawError = new WeakMap<object, PromptResponseEvidence>();

/** Retained stream evidence for either an explicit terminal error or a raw iterator failure. */
export function promptResponseEvidenceFromError(error: unknown): PromptResponseEvidence | undefined {
  if (error instanceof PromptResponseTerminalError) return error.partial;
  return typeof error === "object" && error !== null
    ? partialEvidenceByRawError.get(error)
    : undefined;
}

export type PromptToolChoice = NonNullable<ResponseCreateParams["tool_choice"]>;
export type PromptActivityCallback = (event: ResponseStreamEvent) => void;
export type PromptResponseStream = AsyncIterable<ResponseStreamEvent>;

export interface PromptResponseArgs {
  agentName: string;
  version?: string;
  conversationId: string;
  input: ResponseInputItem[];
}

export interface PromptResponseDispatchOptions {
  signal?: AbortSignal;
  timeoutMs?: number;
  toolChoice?: PromptToolChoice;
}

export interface PreparedPromptResponse {
  readonly agentName: string;
  readonly version?: string;
  readonly conversationId: string;
  /** Serialized at dispatch time so later mutation cannot rebind the stream. */
  readonly serializedInput: string;
  /** Undefined and explicit auto are equivalent ordinary first-round choices. */
  readonly serializedToolChoice: string;
  readonly stream: PromptResponseStream;
}

export interface CollectPromptResponseOptions extends PromptResponseDispatchOptions {
  onTextDelta?: (delta: string) => void;
  onActivity?: PromptActivityCallback;
  /** Already-dispatched first stream; collection consumes it without replaying create(). */
  preparedResponse?: PreparedPromptResponse;
}

function promptDispatchAbortReason(signal: AbortSignal): Error {
  if (signal.reason instanceof Error) return signal.reason;
  return Object.assign(new Error("Prompt response aborted before dispatch"), { name: "AbortError" });
}

function serializePromptToolChoice(toolChoice: PromptToolChoice | undefined): string {
  return JSON.stringify(toolChoice ?? "auto");
}

interface HostedStreamEvent {
  type?: string;
  delta?: string;
  response?: { id?: string; model?: string; agent_session_id?: string };
}

/**
 * Hosted stream-and-collect. Hosted agents are stateless containers: pass the
 * FULL transcript as `input`, stream, collect to a final result. NO project
 * `conversation` (hosted rejects it) and NO agent_reference.
 *
 * Pass opts.agentSessionId only when a turn must reuse a sandbox ($HOME/files);
 * It is left unset by default (the value is captured + returned for later use).
 *
 * Does NOT catch — raw SDK/OpenAI errors propagate so each surface maps them via
 * its existing taxonomy (mapFoundryError / mapOpenAIError).
 */
export async function collectHostedResponse(
  client: OpenAIClient,
  input: InvokeMessage[],
  opts?: { agentSessionId?: string; signal?: AbortSignal },
): Promise<CollectedResponse> {
  const body: Record<string, unknown> = { input, stream: true };
  if (opts?.agentSessionId) body.agent_session_id = opts.agentSessionId;
  const responses = (client as unknown as {
    responses: { create: (b: Record<string, unknown>, options?: { signal?: AbortSignal }) => Promise<AsyncIterable<HostedStreamEvent>> };
  }).responses;
  const stream = await (opts?.signal
    ? responses.create(body, { signal: opts.signal })
    : responses.create(body));

  let text = "";
  let responseId = "";
  let model: string | undefined;
  let agentSessionId: string | undefined;
  for await (const ev of stream) {
    if (ev.type === "response.output_text.delta" && typeof ev.delta === "string") {
      text += ev.delta;
    }
    if (ev.response) {
      if (ev.response.id) responseId = ev.response.id;
      if (ev.response.model) model = ev.response.model;
      if (ev.response.agent_session_id) agentSessionId = ev.response.agent_session_id;
    }
  }
  return { text, responseId, model, agentSessionId };
}

/** Dispatch a prompt response without consuming its stream. */
export async function preparePromptResponse(
  client: OpenAIClient,
  args: PromptResponseArgs,
  opts?: PromptResponseDispatchOptions,
): Promise<PreparedPromptResponse> {
  if (opts?.signal?.aborted) throw promptDispatchAbortReason(opts.signal);
  const agent_reference: { name: string; type: "agent_reference"; version?: string } = {
    name: args.agentName,
    type: "agent_reference",
  };
  if (args.version) agent_reference.version = args.version;

  const extra: {
    body: { agent_reference: typeof agent_reference };
    signal?: AbortSignal;
    timeout?: number;
    maxRetries: 0;
  } = {
    body: { agent_reference },
    maxRetries: 0,
  };
  if (opts?.signal) extra.signal = opts.signal;
  if (opts?.timeoutMs) extra.timeout = opts.timeoutMs;

  const serializedInput = JSON.stringify(args.input);
  const serializedToolChoice = serializePromptToolChoice(opts?.toolChoice);
  const stream = (await (client as unknown as {
    responses: {
      create: (
        body: Record<string, unknown>,
        extra: { body: unknown; signal?: AbortSignal; timeout?: number; maxRetries: number },
      ) => Promise<AsyncIterable<ResponseStreamEvent>>;
    };
  }).responses.create(
    {
      conversation: args.conversationId,
      input: args.input,
      stream: true,
      ...(opts?.toolChoice === undefined ? {} : { tool_choice: opts.toolChoice }),
    },
    extra,
  ));
  return Object.freeze({
    agentName: args.agentName,
    ...(args.version === undefined ? {} : { version: args.version }),
    conversationId: args.conversationId,
    serializedInput,
    serializedToolChoice,
    stream,
  });
}

function assertPreparedPromptResponseIdentity(
  prepared: PreparedPromptResponse,
  args: PromptResponseArgs,
  toolChoice: PromptToolChoice | undefined,
): void {
  const matches =
    prepared.agentName === args.agentName &&
    prepared.version === args.version &&
    prepared.conversationId === args.conversationId &&
    prepared.serializedInput === JSON.stringify(args.input) &&
    prepared.serializedToolChoice === serializePromptToolChoice(toolChoice);
  if (!matches) {
    const error = new Error("Prepared prompt response does not match the canonical request");
    error.name = "CanonicalTurnProtocolError";
    throw error;
  }
}

/**
 * Streaming agent_reference invoke for PROMPT agents — the conversation-scoped
 * counterpart to collectHostedResponse, generalizing apps/web/scripts/f1-smoke-turn.ts.
 *
 * PURE: does NOT rotate / retry / catch (raw SDK/OpenAI errors propagate, same
 * contract as collectHostedResponse). Caller MUST pass a FRESH conversationId per
 * turn (Foundry appends `input` server-side). `version` is a DEFENSIVE pin to THIS
 * worker's latest known-loader version — NOT an arm selector.
 *
 * usage is parsed from the terminal response.completed event's response.usage
 * (EXPECTED source, pending live confirmation). Absent usage -> undefined
 * (never a fabricated 0); the nullable cost contract covers that downstream.
 */
export async function collectPromptResponse(
  client: OpenAIClient,
  args: PromptResponseArgs,
  opts?: CollectPromptResponseOptions,
): Promise<CollectedPromptResponse> {
  const prepared = opts?.preparedResponse ?? await preparePromptResponse(client, args, opts);
  if (opts?.preparedResponse) {
    assertPreparedPromptResponseIdentity(prepared, args, opts.toolChoice);
  }
  const stream = prepared.stream;

  let text = "";
  let responseId = "";
  let model: string | undefined;
  let usage: InvokeUsage | undefined;
  let output: ResponseOutputItem[] = [];
  const toolTrace: string[] = [];

  const captureResponse = (response: Response, includeOutput: boolean): void => {
    responseId = response.id;
    model = response.model;
    if (includeOutput) output = response.output;
    const u = response.usage;
    if (u && typeof u.input_tokens === "number" && typeof u.output_tokens === "number") {
      usage = {
        inputTokens: u.input_tokens,
        outputTokens: u.output_tokens,
        totalTokens: typeof u.total_tokens === "number" ? u.total_tokens : u.input_tokens + u.output_tokens,
      };
    }
  };
  const evidence = (terminalState: PromptResponseTerminalState): PromptResponseEvidence => ({
    text,
    responseId,
    ...(model === undefined ? {} : { model }),
    ...(usage === undefined ? {} : { usage }),
    toolTrace,
    output,
    terminalState,
  });

  try {
    for await (const ev of stream) {
      opts?.onActivity?.(ev);
      if (ev.type === "response.output_text.delta") {
        text += ev.delta;
        opts?.onTextDelta?.(ev.delta);
        continue;
      }
      if (ev.type === "response.output_item.added" || ev.type === "response.output_item.done") {
        const item = ev.item as ResponseOutputItem & {
          name?: string;
          server_label?: string;
          status?: string;
        };
        const prefix = ev.type === "response.output_item.added" ? "+" : "✓";
        const label =
          `${prefix}${item.type}` +
          (item.name ? `:${item.name}` : "") +
          (item.server_label ? `@${item.server_label}` : "") +
          (item.status ? ` (${item.status})` : "");
        toolTrace.push(label);
        if (ev.type === "response.output_item.done") output.push(ev.item);
        continue;
      }
      if (ev.type === "response.completed") {
        captureResponse(ev.response, true);
        return { ...evidence("completed"), terminalState: "completed" };
      }
      if (ev.type === "response.failed") {
        captureResponse(ev.response, true);
        throw new PromptResponseTerminalError(
          "failed",
          ev.response.error?.message ?? "Prompt response failed",
          evidence("failed"),
        );
      }
      if (ev.type === "response.incomplete") {
        captureResponse(ev.response, true);
        const reason = ev.response.incomplete_details?.reason ?? "unknown";
        throw new PromptResponseTerminalError(
          "incomplete",
          `Prompt response incomplete (${reason})`,
          evidence("incomplete"),
        );
      }
      if (ev.type === "error") {
        throw new PromptResponseTerminalError("error", ev.message, evidence("error"));
      }
      if ("response" in ev) captureResponse(ev.response, false);
    }
  } catch (error) {
    if (error instanceof PromptResponseTerminalError) throw error;
    if (typeof error === "object" && error !== null) {
      partialEvidenceByRawError.set(error, evidence("error"));
    }
    throw error;
  }

  throw new PromptResponseTerminalError(
    "eof",
    "Prompt response stream ended without a terminal event",
    evidence("eof"),
  );
}
