// The Foundry SDK's AgentKind also includes "workflow"; kindFromAgentRecord maps
// anything that isn't "hosted" to "prompt" as a safe default — workflow agents
// are out of scope for this epic (prompt + hosted only).
export type WorkerKind = "prompt" | "hosted";

export interface HostedBlock {
  containerImage?: string;
  protocols: string[];
  sandbox?: { cpu: string; memory: string };
  versionStatus?: "creating" | "active" | "failed" | "deleting" | "deleted";
}

/** Minimal structural shape of a record from agents.list() / agents.get(). */
export interface RawAgentVersionLike {
  status?: string;
  definition?: {
    kind?: string;
    image?: string;
    cpu?: string;
    memory?: string;
    container_protocol_versions?: { protocol?: string }[];
    protocol_versions?: { protocol?: string }[];
  };
}
export interface RawAgentLike {
  versions?: { latest?: RawAgentVersionLike };
}

/** Authoritative kind discriminator: versions.latest.definition.kind. */
export function kindFromAgentRecord(raw: RawAgentLike): WorkerKind {
  return raw.versions?.latest?.definition?.kind === "hosted" ? "hosted" : "prompt";
}

/** The hosted metadata block, present only for hosted agents. */
export function hostedBlockFromAgentRecord(raw: RawAgentLike): HostedBlock | undefined {
  const version = raw.versions?.latest;
  const def = version?.definition;
  if (def?.kind !== "hosted") return undefined;
  const protocols = (def.container_protocol_versions ?? def.protocol_versions ?? [])
    .map((p) => p.protocol)
    .filter((p): p is string => typeof p === "string");
  const block: HostedBlock = { protocols };
  if (def.image) block.containerImage = def.image;
  if (def.cpu && def.memory) block.sandbox = { cpu: def.cpu, memory: def.memory };
  if (version?.status) block.versionStatus = version.status as HostedBlock["versionStatus"];
  return block;
}
